import { API_URL } from '../config.js';
import { pingBackend } from '../services/debug/connectivity.js';
import { createComponentLogger } from '../utils/component-logger.js';

const log = createComponentLogger('app');

/**
 * "Can we reach the API?" — the question first boot actually needs to answer
 * (story 267).
 *
 * `navigator.onLine` answers a different, weaker question: does this device
 * have *a* network. On 2026-07-25 19:08 the phone was off the LAN with mobile
 * data up, so `navigator.onLine` was `true` while the API (a LAN host reachable
 * only through WireGuard) had no route at all. Bootstrap therefore took the
 * loud `empty-failed` path — three retries and a `console.error` accusing the
 * server of a fault it never had — instead of the quiet `empty-offline` one.
 *
 * The probe reuses `pingBackend`, whose `ok` contract is already "reached the
 * server, regardless of HTTP status" — exactly this question. It targets
 * `${API_URL}/health`, deliberately NOT a `/api/*` path: the service worker
 * intercepts `/api/*` and falls back to the offline router, which answers from
 * inside the browser and would make an unroutable API look reachable (that is
 * literally what the 07-25 log shows). `/health` must fail `isApiRequest`, so
 * that it is passed straight through to the network and the answer is the
 * network's, not ours.
 *
 * **That invariant was false in production for the whole of stories 267–295.**
 * `isApiRequest` derived its prefix from `new URL(API_URL).pathname`, which is
 * `/` for an origin-only `API_URL`, so it claimed every path on the API origin
 * — `/health` included — and this probe answered `true` for an API with no
 * route to it. It is now `isApiRequestUrl` in
 * `services/offline/service-worker-api-scope.ts`, which pins `/health` in its
 * own test. Nothing here can assert it: these tests inject `fetch`, so they
 * never exercise the service worker's interception, and that gap is exactly
 * how the wrong assumption survived a year of green suites.
 */

/**
 * Probe cap. The negative answer this probe produces skips the remaining
 * download attempts *and* their backoff (`DEFAULT_BACKOFFS_MS` totals 900ms;
 * the two skipped attempts against an unroutable host took 4s and 10s in the
 * 07-25 log). Capping the probe below the backoff alone keeps its cost charged
 * against the budget it removes rather than added to it. A positive answer
 * costs only real LAN latency, and at most one probe can ever hit the timeout
 * because a negative answer ends the retry loop.
 */
export const API_REACHABILITY_TIMEOUT_MS = 800;

export interface ApiReachabilityOptions {
    /** Defaults to the app's own API origin `/health` (never a `/api/*` path — see above). */
    url?: string;
    timeoutMs?: number;
    /** Injected in tests; production reads `navigator.onLine`. */
    onLine?: () => boolean;
}

function browserIsOnline(): boolean {
    return typeof navigator === 'undefined' ? true : navigator.onLine;
}

export async function isApiReachable(options: ApiReachabilityOptions = {}): Promise<boolean> {
    const url = options.url ?? `${API_URL}/health`;
    const timeoutMs = options.timeoutMs ?? API_REACHABILITY_TIMEOUT_MS;
    const onLine = options.onLine ?? browserIsOnline;

    const result = await pingBackend(url, timeoutMs);
    if (result.ok) {
        return true;
    }

    if (onLine()) {
        // The 07-25 shape. `info`, not `error`: nothing is broken — this device
        // simply is not on the network the API lives on.
        log.info(
            `API unreachable while navigator.onLine === true: this device HAS a network but cannot reach the API at ${url} ` +
            `(off the LAN / WireGuard down) — not a server fault. Probe: ${result.error} (${result.latencyMs}ms, cap ${timeoutMs}ms)`,
        );
    } else {
        log.debug(`API unreachable and navigator.onLine === false — genuinely offline (${url})`);
    }
    return false;
}
